-- ---------------------------------------------------------------- user-defined table types (TVP)
CREATE TYPE erp.IdList AS TABLE (Id INT NOT NULL PRIMARY KEY);
GO
CREATE TYPE erp.OrderLineType AS TABLE (
    ProductId INT NOT NULL, Qty DECIMAL(18,4) NOT NULL, UnitPrice DECIMAL(18,4) NOT NULL);
GO

-- ---------------------------------------------------------------- tables (PK + indexes + computed columns)
-- NOTE: tables are created WITHOUT inline FOREIGN KEY constraints so create order
-- never matters; every FK is added afterwards via ALTER TABLE (see next section).
CREATE TABLE erp.Currency (
    CurrencyCode NCHAR(3) NOT NULL PRIMARY KEY,
    Name         NVARCHAR(60) NOT NULL,
    Rate         DECIMAL(18,6) NOT NULL DEFAULT 1.0
);
GO
CREATE TABLE erp.Region (
    RegionId INT NOT NULL PRIMARY KEY,
    Name     NVARCHAR(80) NOT NULL,
    Code     NVARCHAR(10) NULL
);
GO
CREATE TABLE erp.Account (
    AccountId       INT NOT NULL PRIMARY KEY,
    Name            NVARCHAR(120) NOT NULL,
    ParentAccountId INT NULL
);
GO
CREATE TABLE erp.Warehouse (
    WarehouseId INT NOT NULL PRIMARY KEY,
    Name        NVARCHAR(80) NOT NULL,
    RegionId    INT NULL
);
GO
CREATE TABLE erp.Customer (
    CustomerId INT NOT NULL PRIMARY KEY,
    Name       NVARCHAR(120) NOT NULL,
    Tier       NVARCHAR(10) NOT NULL DEFAULT 'STD',
    RegionId   INT NULL,
    CreditLimit DECIMAL(18,2) NOT NULL DEFAULT 0
);
GO
CREATE TABLE erp.Supplier (
    SupplierId   INT NOT NULL PRIMARY KEY,
    Name         NVARCHAR(120) NOT NULL,
    CurrencyCode NCHAR(3) NOT NULL DEFAULT 'USD',
    RegionId     INT NULL
);
GO
CREATE TABLE erp.ProductCategory (
    CategoryId INT NOT NULL PRIMARY KEY,
    Name       NVARCHAR(80) NOT NULL,
    ParentCategoryId INT NULL
);
GO
CREATE TABLE erp.Product (
    ProductId      INT NOT NULL PRIMARY KEY,
    Sku            NVARCHAR(40) NOT NULL,
    CategoryId     INT NULL,
    StdCost        DECIMAL(18,4) NOT NULL DEFAULT 0,
    ListPrice      DECIMAL(18,4) NOT NULL DEFAULT 0,
    Margin         AS (ListPrice - StdCost),
    MarginPct      AS (CASE WHEN ListPrice = 0 THEN 0 ELSE (ListPrice - StdCost) / ListPrice END) PERSISTED,
    IsManufactured BIT NOT NULL DEFAULT 0
);
GO
CREATE INDEX IX_Product_Category ON erp.Product(CategoryId);
GO
CREATE TABLE erp.Inventory (
    ProductId    INT NOT NULL,
    WarehouseId  INT NOT NULL,
    QtyOnHand    DECIMAL(18,4) NOT NULL DEFAULT 0,
    QtyAllocated DECIMAL(18,4) NOT NULL DEFAULT 0,
    QtyAvailable AS (QtyOnHand - QtyAllocated),
    CONSTRAINT PK_Inventory PRIMARY KEY (ProductId, WarehouseId)
);
GO
CREATE TABLE erp.InventoryTxn (
    TxnId       INT IDENTITY(1,1) PRIMARY KEY,
    ProductId   INT NOT NULL,
    WarehouseId INT NOT NULL,
    QtyDelta    DECIMAL(18,4) NOT NULL DEFAULT 0,
    TxnTs       DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
);
GO
CREATE TABLE erp.SupplierProduct (
    SupplierId INT NOT NULL,
    ProductId  INT NOT NULL,
    UnitCost   DECIMAL(18,4) NOT NULL DEFAULT 0,
    LeadDays   INT NOT NULL DEFAULT 7,
    CONSTRAINT PK_SupplierProduct PRIMARY KEY (SupplierId, ProductId)
);
GO
CREATE TABLE erp.SupplierScore (
    ScoreId       INT IDENTITY(1,1) PRIMARY KEY,
    SupplierId    INT NOT NULL,
    QualityScore  DECIMAL(9,4) NOT NULL DEFAULT 0,
    DeliveryScore DECIMAL(9,4) NOT NULL DEFAULT 0,
    PriceScore    DECIMAL(9,4) NOT NULL DEFAULT 0,
    ScoreDate     DATE NOT NULL DEFAULT CAST(SYSUTCDATETIME() AS DATE)
);
GO
CREATE TABLE erp.Bom (
    BomId     INT NOT NULL PRIMARY KEY,
    ProductId INT NOT NULL,
    IsActive  BIT NOT NULL DEFAULT 1
);
GO
CREATE TABLE erp.BomComponent (
    BomComponentId     INT NOT NULL PRIMARY KEY,
    BomId              INT NOT NULL,
    ComponentProductId INT NOT NULL,
    QtyPer             DECIMAL(18,4) NOT NULL DEFAULT 1
);
GO
CREATE TABLE erp.SalesOrder (
    OrderId    INT NOT NULL PRIMARY KEY,
    CustomerId INT NOT NULL,
    OrderDate  DATE NOT NULL DEFAULT CAST(SYSUTCDATETIME() AS DATE),
    Total      DECIMAL(18,2) NOT NULL DEFAULT 0,
    Status     NVARCHAR(20) NOT NULL DEFAULT 'NEW',
    IsDeleted  BIT NOT NULL DEFAULT 0
);
GO
CREATE INDEX IX_SalesOrder_Customer ON erp.SalesOrder(CustomerId);
GO
CREATE TABLE erp.SalesOrderLine (
    LineId    INT NOT NULL PRIMARY KEY,
    OrderId   INT NOT NULL,
    ProductId INT NOT NULL,
    Qty       DECIMAL(18,4) NOT NULL DEFAULT 1,
    UnitPrice DECIMAL(18,4) NOT NULL DEFAULT 0,
    LineTotal AS (Qty * UnitPrice) PERSISTED
);
GO
CREATE INDEX IX_SalesOrderLine_Order ON erp.SalesOrderLine(OrderId);
GO
CREATE TABLE erp.PurchaseOrder (
    PoId       INT NOT NULL PRIMARY KEY,
    SupplierId INT NOT NULL,
    Status     NVARCHAR(20) NOT NULL DEFAULT 'OPEN',
    Total      DECIMAL(18,2) NOT NULL DEFAULT 0
);
GO
CREATE TABLE erp.PurchaseOrderLine (
    PoLineId  INT NOT NULL PRIMARY KEY,
    PoId      INT NOT NULL,
    ProductId INT NOT NULL,
    Qty       DECIMAL(18,4) NOT NULL DEFAULT 1,
    UnitCost  DECIMAL(18,4) NOT NULL DEFAULT 0
);
GO
CREATE TABLE erp.PurchaseReq (
    ReqId     INT NOT NULL PRIMARY KEY,
    ProductId INT NOT NULL,
    Qty       DECIMAL(18,4) NOT NULL DEFAULT 1,
    Status    NVARCHAR(20) NOT NULL DEFAULT 'NEW'
);
GO
CREATE TABLE erp.PurchaseReqLine (
    ReqLineId INT NOT NULL PRIMARY KEY,
    ReqId     INT NOT NULL,
    ProductId INT NOT NULL,
    Qty       DECIMAL(18,4) NOT NULL DEFAULT 1
);
GO
CREATE TABLE erp.CostLedger (
    LedgerId  INT IDENTITY(1,1) PRIMARY KEY,
    ProductId INT NOT NULL,
    CostType  NVARCHAR(20) NOT NULL DEFAULT 'STD',
    Amount    DECIMAL(18,4) NOT NULL DEFAULT 0,
    PostedTs  DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
);
GO
CREATE TABLE erp.JournalEntry (
    JournalId INT NOT NULL PRIMARY KEY,
    EntryDate DATE NOT NULL DEFAULT CAST(SYSUTCDATETIME() AS DATE),
    Memo      NVARCHAR(200) NULL
);
GO
CREATE TABLE erp.JournalLine (
    JournalLineId INT NOT NULL PRIMARY KEY,
    JournalId     INT NOT NULL,
    AccountId     INT NOT NULL,
    Debit         DECIMAL(18,2) NOT NULL DEFAULT 0,
    Credit        DECIMAL(18,2) NOT NULL DEFAULT 0
);
GO
CREATE TABLE erp.AuditTrail (
    AuditId  INT IDENTITY(1,1) PRIMARY KEY,
    Area     NVARCHAR(40) NULL,
    RefId    INT NULL,
    Action   NVARCHAR(60) NULL,
    Detail   NVARCHAR(400) NULL,
    LoggedTs DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
);
GO

-- ---------------------------------------------------------------- foreign keys (added AFTER all tables exist)
-- All parent tables are guaranteed to exist here, so ordering is irrelevant.
