ALTER TABLE erp.Warehouse       ADD CONSTRAINT FK_Warehouse_Region  FOREIGN KEY (RegionId)        REFERENCES erp.Region(RegionId);
ALTER TABLE erp.Customer        ADD CONSTRAINT FK_Customer_Region   FOREIGN KEY (RegionId)        REFERENCES erp.Region(RegionId);
ALTER TABLE erp.Supplier        ADD CONSTRAINT FK_Supplier_Currency FOREIGN KEY (CurrencyCode)    REFERENCES erp.Currency(CurrencyCode);
ALTER TABLE erp.Supplier        ADD CONSTRAINT FK_Supplier_Region   FOREIGN KEY (RegionId)        REFERENCES erp.Region(RegionId);
ALTER TABLE erp.Product         ADD CONSTRAINT FK_Product_Category  FOREIGN KEY (CategoryId)      REFERENCES erp.ProductCategory(CategoryId);
ALTER TABLE erp.Inventory       ADD CONSTRAINT FK_Inventory_Product   FOREIGN KEY (ProductId)   REFERENCES erp.Product(ProductId);
ALTER TABLE erp.Inventory       ADD CONSTRAINT FK_Inventory_Warehouse FOREIGN KEY (WarehouseId) REFERENCES erp.Warehouse(WarehouseId);
ALTER TABLE erp.SupplierProduct ADD CONSTRAINT FK_SP_Supplier FOREIGN KEY (SupplierId) REFERENCES erp.Supplier(SupplierId);
ALTER TABLE erp.SupplierProduct ADD CONSTRAINT FK_SP_Product  FOREIGN KEY (ProductId)  REFERENCES erp.Product(ProductId);
ALTER TABLE erp.SupplierScore   ADD CONSTRAINT FK_SS_Supplier FOREIGN KEY (SupplierId) REFERENCES erp.Supplier(SupplierId);
ALTER TABLE erp.Bom             ADD CONSTRAINT FK_Bom_Product FOREIGN KEY (ProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.BomComponent    ADD CONSTRAINT FK_BC_Bom       FOREIGN KEY (BomId)              REFERENCES erp.Bom(BomId);
ALTER TABLE erp.BomComponent    ADD CONSTRAINT FK_BC_Component FOREIGN KEY (ComponentProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.SalesOrder      ADD CONSTRAINT FK_SO_Customer FOREIGN KEY (CustomerId) REFERENCES erp.Customer(CustomerId);
ALTER TABLE erp.SalesOrderLine  ADD CONSTRAINT FK_SOL_Order   FOREIGN KEY (OrderId)   REFERENCES erp.SalesOrder(OrderId);
ALTER TABLE erp.SalesOrderLine  ADD CONSTRAINT FK_SOL_Product FOREIGN KEY (ProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.PurchaseOrder     ADD CONSTRAINT FK_PO_Supplier FOREIGN KEY (SupplierId) REFERENCES erp.Supplier(SupplierId);
ALTER TABLE erp.PurchaseOrderLine ADD CONSTRAINT FK_POL_Po      FOREIGN KEY (PoId)      REFERENCES erp.PurchaseOrder(PoId);
ALTER TABLE erp.PurchaseOrderLine ADD CONSTRAINT FK_POL_Product FOREIGN KEY (ProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.PurchaseReq      ADD CONSTRAINT FK_PR_Product  FOREIGN KEY (ProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.PurchaseReqLine  ADD CONSTRAINT FK_PRL_Req     FOREIGN KEY (ReqId)     REFERENCES erp.PurchaseReq(ReqId);
ALTER TABLE erp.PurchaseReqLine  ADD CONSTRAINT FK_PRL_Product FOREIGN KEY (ProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.CostLedger  ADD CONSTRAINT FK_CL_Product FOREIGN KEY (ProductId) REFERENCES erp.Product(ProductId);
ALTER TABLE erp.JournalLine ADD CONSTRAINT FK_JL_Journal FOREIGN KEY (JournalId) REFERENCES erp.JournalEntry(JournalId);
ALTER TABLE erp.JournalLine ADD CONSTRAINT FK_JL_Account FOREIGN KEY (AccountId) REFERENCES erp.Account(AccountId);
