        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT o.CustomerId, ol.ProductId, SUM(ol.Qty) AS Q
            FROM erp.SalesOrder o INNER JOIN erp.SalesOrderLine ol ON ol.OrderId = o.OrderId
            GROUP BY GROUPING SETS ((o.CustomerId, ol.ProductId), (o.CustomerId), ())
        ) g173;
        -- stage 174: OFFSET / FETCH paging + CASE expression
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT o.OrderId,
                   CASE WHEN o.Total >= 1000 THEN N'BIG' WHEN o.Total >= 100 THEN N'MID' ELSE N'SMALL' END AS Band
            FROM erp.SalesOrder o
            ORDER BY o.OrderId
            OFFSET 0 ROWS FETCH NEXT 50 ROWS ONLY
        ) p174;
        -- stage 175: global temp table (##) with OUTPUT clause capturing inserted rows
        IF OBJECT_ID('tempdb..##g175') IS NOT NULL DROP TABLE ##g175;
        CREATE TABLE ##g175(ProductId INT, Sku NVARCHAR(40));
        INSERT INTO ##g175(ProductId, Sku)
        OUTPUT inserted.ProductId INTO @outbuf(ProductId)
        SELECT p.ProductId, p.Sku FROM erp.Product p WHERE p.ProductId > 0;
        SET @cnt = @cnt + (SELECT COUNT(*) FROM ##g175);
        DROP TABLE ##g175;
        -- stage 176: deeply nested subqueries
        SELECT @cnt = @cnt + ISNULL((
            SELECT COUNT(*) FROM erp.Product p WHERE p.ProductId IN (
                SELECT ol.ProductId FROM erp.SalesOrderLine ol WHERE ol.OrderId IN (
                    SELECT o.OrderId FROM erp.SalesOrder o WHERE o.CustomerId IN (
                        SELECT c.CustomerId FROM erp.Customer c WHERE c.RegionId IN (
                            SELECT r.RegionId FROM erp.Region r WHERE r.RegionId > 0)))))
        , 0);
        -- stage 177: user-defined TABLE TYPE variable (table-valued) populated + joined
        DECLARE @ids177 erp.IdList;
        INSERT INTO @ids177(Id) SELECT ProductId FROM erp.Product WHERE ProductId > 0;
        SELECT @cnt = @cnt + COUNT(*) FROM erp.Product p INNER JOIN @ids177 x ON x.Id = p.ProductId;
        -- stage 178: self-join over account hierarchy
        SELECT @cnt = @cnt + COUNT(*)
        FROM erp.Account a
        LEFT JOIN erp.Account parent ON parent.AccountId = a.ParentAccountId;
        -- stage 179: dynamic SQL via EXEC(@sql) string concatenation
        DECLARE @dx179 NVARCHAR(MAX) = N'UPDATE erp.SalesOrder SET Status = Status WHERE 1 = 0';
        EXEC(@dx179);
        -- stage 180: multi-table join report into a table variable (LEFT/INNER joins, ISNULL/COALESCE)
        DECLARE @rep180 TABLE(ProductId INT, Sku NVARCHAR(40), Category NVARCHAR(80), OnHand DECIMAL(18,4), Supplier NVARCHAR(120));
        INSERT INTO @rep180(ProductId, Sku, Category, OnHand, Supplier)
        SELECT p.ProductId, p.Sku, pc.Name, ISNULL(inv.QtyOnHand,0), COALESCE(s.Name, N'<none>')
        FROM erp.Product p
        LEFT JOIN erp.ProductCategory pc ON pc.CategoryId = p.CategoryId
        LEFT JOIN erp.Inventory inv ON inv.ProductId = p.ProductId
        LEFT JOIN erp.SupplierProduct sp ON sp.ProductId = p.ProductId
        LEFT JOIN erp.Supplier s ON s.SupplierId = sp.SupplierId
        INNER JOIN erp.Currency cur ON cur.CurrencyCode = s.CurrencyCode
        WHERE p.IsManufactured = 0 AND (@cnt IS NULL OR p.ProductId > 0);
        SET @cnt = @cnt + (SELECT COUNT(*) FROM @rep180);
        -- stage 181: window-function ranking over inventory (ROW_NUMBER/RANK/SUM/LAG/LEAD OVER)
        ;WITH ranked181 AS (
            SELECT inv.ProductId, inv.WarehouseId, inv.QtyOnHand,
                   ROW_NUMBER() OVER (PARTITION BY inv.ProductId ORDER BY inv.QtyOnHand DESC) AS rn,
                   RANK()       OVER (PARTITION BY inv.ProductId ORDER BY inv.QtyOnHand DESC) AS rk,
                   SUM(inv.QtyOnHand) OVER (PARTITION BY inv.ProductId) AS totQty,
                   LAG(inv.QtyOnHand)  OVER (PARTITION BY inv.ProductId ORDER BY inv.WarehouseId) AS prevQty,
                   LEAD(inv.QtyOnHand) OVER (PARTITION BY inv.ProductId ORDER BY inv.WarehouseId) AS nextQty
            FROM erp.Inventory inv
            INNER JOIN erp.Warehouse wh ON wh.WarehouseId = inv.WarehouseId
        )
        SELECT @cnt = @cnt + COUNT(*) FROM ranked181 WHERE rn = 1;
        -- stage 182: MERGE upsert into inventory (WHEN MATCHED / WHEN NOT MATCHED)
        MERGE erp.Inventory AS tgt
        USING (SELECT ol.ProductId, SUM(ol.Qty) AS Q FROM erp.SalesOrderLine ol
               INNER JOIN erp.SalesOrder o ON o.OrderId = ol.OrderId
               WHERE o.IsDeleted = 0 GROUP BY ol.ProductId) AS src
            ON tgt.ProductId = src.ProductId
        WHEN MATCHED THEN UPDATE SET tgt.QtyAllocated = tgt.QtyAllocated + src.Q * 0
        WHEN NOT MATCHED THEN INSERT(ProductId, WarehouseId, QtyOnHand) VALUES(src.ProductId, 1, 0);
        -- stage 183: dynamic SQL (sp_executesql with typed param)
        DECLARE @sql183 NVARCHAR(MAX) = N'
            SELECT o.OrderId, c.Name, c.Tier, o.Total, r.Name AS Region
            FROM erp.SalesOrder o
            INNER JOIN erp.Customer c ON c.CustomerId = o.CustomerId
            LEFT JOIN erp.Region r ON r.RegionId = c.RegionId
            LEFT JOIN erp.SalesOrderLine ol ON ol.OrderId = o.OrderId
            LEFT JOIN erp.Product p ON p.ProductId = ol.ProductId
            WHERE o.IsDeleted = 0';
        IF @cnt > 0 SET @sql183 = @sql183 + N' AND o.Total > @minTot';
        EXEC sp_executesql @sql183, N'@minTot DECIMAL(18,2)', @minTot = 0;
        -- stage 184: aggregate + correlated subquery (EXISTS)
        SELECT @cnt = @cnt + ISNULL(SUM(t.ProductId),0)
        FROM erp.SalesOrderLine t
        WHERE EXISTS (SELECT 1 FROM erp.Product p WHERE p.ProductId = t.ProductId OR 1=1);
        -- recursive CTE: account hierarchy rollup (depth-guarded via MAXRECURSION)
        ;WITH acc AS (
            SELECT AccountId, ParentAccountId, 0 AS Lvl FROM erp.Account WHERE ParentAccountId IS NULL
            UNION ALL
            SELECT a.AccountId, a.ParentAccountId, p.Lvl+1 FROM erp.Account a INNER JOIN acc p ON a.ParentAccountId = p.AccountId
        )
        SELECT @cnt = @cnt + COUNT(*) FROM acc OPTION (MAXRECURSION 50);
        SET @factor = erp.fn_DiscountFactor(CAST(@cnt AS DECIMAL(18,2)));
        SET @score  = erp.fn_SupplierScore(ISNULL(@supId,1));
        SET @unit   = erp.fn_UnitCost(ISNULL(@prodId,1), ISNULL(@supId,1));
        SELECT @cnt = @cnt + COUNT(*) FROM erp.fn_ExplodeBomTvf(ISNULL(@prodId,1), @xQty);
        SELECT @cnt = @cnt + COUNT(*) FROM erp.fn_ProductCostTvf(ISNULL(@prodId,1));
        -- sequences (NEXT VALUE FOR)
        SET @xOrder = NEXT VALUE FOR erp.OrderNumberSeq;
        SET @xReq   = NEXT VALUE FOR erp.ReqNumberSeq;
        SET @poId   = NEXT VALUE FOR erp.PoNumberSeq;
        -- read the views (regular + indexed view)
        SELECT @cnt = @cnt + COUNT(*) FROM erp.vw_OrderSummary;
        SELECT @cnt = @cnt + COUNT(*) FROM erp.vw_ProductInventory;
        SELECT @cnt = @cnt + COUNT(*) FROM erp.vw_SupplierRanking;
        SELECT @cnt = @cnt + COUNT(*) FROM erp.vw_ProductSales WITH (NOEXPAND);
        -- touch trigger-bearing tables (no-op) so their triggers are discovered
        UPDATE erp.SalesOrderLine SET Qty = Qty WHERE 1 = 0;
        UPDATE erp.SalesOrder SET Status = Status WHERE 1 = 0;
        UPDATE erp.PurchaseOrder SET Status = Status WHERE 1 = 0;
        UPDATE erp.JournalLine SET Debit = Debit WHERE 1 = 0;
        UPDATE erp.Inventory SET QtyOnHand = QtyOnHand WHERE 1 = 0;
        -- descend to next level
        EXEC erp.usp_ScoreSupplier @prodId, @xQty;
        INSERT INTO erp.AuditTrail(Area, RefId, Action, Detail)
        VALUES(N'usp_EvaluateSuppliers', @cnt, N'COMPLETE', CONCAT(N'factor=', @factor, N' score=', @score));
        COMMIT;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SET @msg = ERROR_MESSAGE();
        INSERT INTO erp.AuditTrail(Area, Action, Detail) VALUES(N'usp_EvaluateSuppliers', N'ERROR', @msg);
        THROW;
    END CATCH
END;
GO

/*======================================================================
  erp.usp_CreatePurchaseReq
  Part of the MRP order-to-cash deep call chain.
  Demonstrates: cursors, WHILE loops, IF/ELSE/CASE, TRY/CATCH, SET XACT_ABORT,
  transactions (BEGIN TRAN/COMMIT/ROLLBACK, SAVE TRANSACTION, @@TRANCOUNT),
  CTEs, recursive CTEs, MERGE, window functions, PIVOT/UNPIVOT, GROUPING SETS,
  OFFSET/FETCH, APPLY, all join types, dynamic SQL, TVPs, OUTPUT, multi-table joins.
======================================================================*/
CREATE PROCEDURE erp.usp_CreatePurchaseReq
    @ProductId INT, @Qty DECIMAL(18,4)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @cnt INT = 0, @i INT = 0, @tmp DECIMAL(18,4) = 0, @msg NVARCHAR(400);
    DECLARE @xOrder INT, @custId INT, @prodId INT, @xQty DECIMAL(18,4) = 1, @supId INT;
    DECLARE @nextLvl INT, @child INT, @xReq INT, @poId INT, @unit DECIMAL(18,4) = 0;
    DECLARE @amt DECIMAL(18,4) = 0, @factor DECIMAL(9,4) = 1, @score DECIMAL(9,4) = 0;
    DECLARE @outbuf TABLE(ProductId INT);
    BEGIN TRY
        BEGIN TRAN;
        SAVE TRANSACTION sp_usp_CreatePurchaseRe;
        -- stage 0: multi-table join report into a table variable (LEFT/INNER joins, ISNULL/COALESCE)
        DECLARE @rep0 TABLE(ProductId INT, Sku NVARCHAR(40), Category NVARCHAR(80), OnHand DECIMAL(18,4), Supplier NVARCHAR(120));
        INSERT INTO @rep0(ProductId, Sku, Category, OnHand, Supplier)
        SELECT p.ProductId, p.Sku, pc.Name, ISNULL(inv.QtyOnHand,0), COALESCE(s.Name, N'<none>')
        FROM erp.Product p
        LEFT JOIN erp.ProductCategory pc ON pc.CategoryId = p.CategoryId
        LEFT JOIN erp.Inventory inv ON inv.ProductId = p.ProductId
        LEFT JOIN erp.SupplierProduct sp ON sp.ProductId = p.ProductId
        LEFT JOIN erp.Supplier s ON s.SupplierId = sp.SupplierId
        INNER JOIN erp.Currency cur ON cur.CurrencyCode = s.CurrencyCode
        WHERE p.IsManufactured = 0 AND (@cnt IS NULL OR p.ProductId > 0);
        SET @cnt = @cnt + (SELECT COUNT(*) FROM @rep0);
        -- stage 1: window-function ranking over inventory (ROW_NUMBER/RANK/SUM/LAG/LEAD OVER)
        ;WITH ranked1 AS (
            SELECT inv.ProductId, inv.WarehouseId, inv.QtyOnHand,
                   ROW_NUMBER() OVER (PARTITION BY inv.ProductId ORDER BY inv.QtyOnHand DESC) AS rn,
                   RANK()       OVER (PARTITION BY inv.ProductId ORDER BY inv.QtyOnHand DESC) AS rk,
                   SUM(inv.QtyOnHand) OVER (PARTITION BY inv.ProductId) AS totQty,
                   LAG(inv.QtyOnHand)  OVER (PARTITION BY inv.ProductId ORDER BY inv.WarehouseId) AS prevQty,
                   LEAD(inv.QtyOnHand) OVER (PARTITION BY inv.ProductId ORDER BY inv.WarehouseId) AS nextQty
            FROM erp.Inventory inv
            INNER JOIN erp.Warehouse wh ON wh.WarehouseId = inv.WarehouseId
        )
        SELECT @cnt = @cnt + COUNT(*) FROM ranked1 WHERE rn = 1;
        -- stage 2: MERGE upsert into inventory (WHEN MATCHED / WHEN NOT MATCHED)
        MERGE erp.Inventory AS tgt
        USING (SELECT ol.ProductId, SUM(ol.Qty) AS Q FROM erp.SalesOrderLine ol
               INNER JOIN erp.SalesOrder o ON o.OrderId = ol.OrderId
               WHERE o.IsDeleted = 0 GROUP BY ol.ProductId) AS src
            ON tgt.ProductId = src.ProductId
        WHEN MATCHED THEN UPDATE SET tgt.QtyAllocated = tgt.QtyAllocated + src.Q * 0
        WHEN NOT MATCHED THEN INSERT(ProductId, WarehouseId, QtyOnHand) VALUES(src.ProductId, 1, 0);
        -- stage 3: dynamic SQL (sp_executesql with typed param)
        DECLARE @sql3 NVARCHAR(MAX) = N'
            SELECT o.OrderId, c.Name, c.Tier, o.Total, r.Name AS Region
            FROM erp.SalesOrder o
            INNER JOIN erp.Customer c ON c.CustomerId = o.CustomerId
            LEFT JOIN erp.Region r ON r.RegionId = c.RegionId
            LEFT JOIN erp.SalesOrderLine ol ON ol.OrderId = o.OrderId
            LEFT JOIN erp.Product p ON p.ProductId = ol.ProductId
            WHERE o.IsDeleted = 0';
        IF @cnt > 0 SET @sql3 = @sql3 + N' AND o.Total > @minTot';
        EXEC sp_executesql @sql3, N'@minTot DECIMAL(18,2)', @minTot = 0;
        -- stage 4: aggregate + correlated subquery (EXISTS)
        SELECT @cnt = @cnt + ISNULL(SUM(t.ProductId),0)
        FROM erp.SalesOrderLine t
        WHERE EXISTS (SELECT 1 FROM erp.Product p WHERE p.ProductId = t.ProductId OR 1=1);
        -- stage 5: cursor loop with IF/ELSE branching + BREAK guard
        DECLARE @cv5 INT, @acc5 DECIMAL(18,4) = 0;
        DECLARE cur5 CURSOR LOCAL FAST_FORWARD FOR SELECT CustomerId FROM erp.Customer WHERE CustomerId IS NOT NULL;
        OPEN cur5; FETCH NEXT FROM cur5 INTO @cv5;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            IF @cv5 % 2 = 0
                SET @acc5 = @acc5 + @cv5;
            ELSE IF @cv5 % 3 = 0
                SET @acc5 = @acc5 + (@cv5 * 2);
            ELSE
                SET @acc5 = @acc5 + 1;
            IF @acc5 > 1000000 BREAK;
            FETCH NEXT FROM cur5 INTO @cv5;
        END
        CLOSE cur5; DEALLOCATE cur5;
        -- stage 6: DDL local temp table (CREATE / INSERT / UPDATE / TRUNCATE / MERGE / DROP)
        CREATE TABLE #stage6(ProductId INT, Qty DECIMAL(18,4), Amt DECIMAL(18,4));
        INSERT INTO #stage6(ProductId, Qty, Amt)
        SELECT ol.ProductId, SUM(ol.Qty), SUM(ol.Qty*ol.UnitPrice)
        FROM erp.SalesOrderLine ol INNER JOIN erp.SalesOrder o ON o.OrderId = ol.OrderId
        WHERE o.IsDeleted = 0 GROUP BY ol.ProductId;
        UPDATE erp.Inventory SET QtyAllocated = QtyAllocated
        FROM erp.Inventory inv INNER JOIN #stage6 st ON st.ProductId = inv.ProductId;
        TRUNCATE TABLE erp.InventoryTxn;
        MERGE erp.CostLedger AS tgt USING #stage6 AS src ON tgt.ProductId = src.ProductId
        WHEN NOT MATCHED THEN INSERT(ProductId, CostType, Amount) VALUES(src.ProductId, N'STD', src.Amt);
        DROP TABLE #stage6;
        -- stage 7: CROSS APPLY + OUTER APPLY over inline TVF, self-join
        SELECT @cnt = @cnt + COUNT(*)
        FROM erp.Product p
        CROSS APPLY erp.fn_ProductCostTvf(p.ProductId) ca
        OUTER APPLY (SELECT TOP 1 sp.UnitCost FROM erp.SupplierProduct sp WHERE sp.ProductId = p.ProductId ORDER BY sp.UnitCost) oa
        INNER JOIN erp.Product p2 ON p2.ProductId = p.ProductId;
        -- stage 8: RIGHT / FULL / CROSS join variety
        SELECT @cnt = @cnt + COUNT(*)
        FROM erp.Warehouse wh
        RIGHT JOIN erp.Inventory inv ON inv.WarehouseId = wh.WarehouseId
        FULL JOIN erp.Product p ON p.ProductId = inv.ProductId
        CROSS JOIN erp.Currency cur
        WHERE (wh.WarehouseId IS NOT NULL OR p.ProductId IS NOT NULL);
        -- stage 9: PIVOT of cost ledger amounts by cost type
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT ProductId, ISNULL([STD],0) AS StdAmt, ISNULL([LANDED],0) AS LandedAmt
            FROM (SELECT ProductId, CostType, Amount FROM erp.CostLedger) srcp
            PIVOT (SUM(Amount) FOR CostType IN ([STD],[LANDED])) AS pvt
        ) q9;
        -- stage 10: UNPIVOT inventory quantity columns into rows
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT ProductId, QtyKind, QtyVal
            FROM (SELECT ProductId, QtyOnHand, QtyAllocated FROM erp.Inventory) srcu
            UNPIVOT (QtyVal FOR QtyKind IN (QtyOnHand, QtyAllocated)) AS unp
        ) q10;
        -- stage 11: GROUPING SETS aggregate
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT o.CustomerId, ol.ProductId, SUM(ol.Qty) AS Q
            FROM erp.SalesOrder o INNER JOIN erp.SalesOrderLine ol ON ol.OrderId = o.OrderId
            GROUP BY GROUPING SETS ((o.CustomerId, ol.ProductId), (o.CustomerId), ())
        ) g11;
        -- stage 12: OFFSET / FETCH paging + CASE expression
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT o.OrderId,
                   CASE WHEN o.Total >= 1000 THEN N'BIG' WHEN o.Total >= 100 THEN N'MID' ELSE N'SMALL' END AS Band
            FROM erp.SalesOrder o
            ORDER BY o.OrderId
            OFFSET 0 ROWS FETCH NEXT 50 ROWS ONLY
        ) p12;
        -- stage 13: global temp table (##) with OUTPUT clause capturing inserted rows
        IF OBJECT_ID('tempdb..##g13') IS NOT NULL DROP TABLE ##g13;
        CREATE TABLE ##g13(ProductId INT, Sku NVARCHAR(40));
        INSERT INTO ##g13(ProductId, Sku)
        OUTPUT inserted.ProductId INTO @outbuf(ProductId)
        SELECT p.ProductId, p.Sku FROM erp.Product p WHERE p.ProductId > 0;
        SET @cnt = @cnt + (SELECT COUNT(*) FROM ##g13);
        DROP TABLE ##g13;
        -- stage 14: deeply nested subqueries
        SELECT @cnt = @cnt + ISNULL((
            SELECT COUNT(*) FROM erp.Product p WHERE p.ProductId IN (
                SELECT ol.ProductId FROM erp.SalesOrderLine ol WHERE ol.OrderId IN (
                    SELECT o.OrderId FROM erp.SalesOrder o WHERE o.CustomerId IN (
                        SELECT c.CustomerId FROM erp.Customer c WHERE c.RegionId IN (
                            SELECT r.RegionId FROM erp.Region r WHERE r.RegionId > 0)))))
        , 0);
        -- stage 15: user-defined TABLE TYPE variable (table-valued) populated + joined
        DECLARE @ids15 erp.IdList;
        INSERT INTO @ids15(Id) SELECT ProductId FROM erp.Product WHERE ProductId > 0;
        SELECT @cnt = @cnt + COUNT(*) FROM erp.Product p INNER JOIN @ids15 x ON x.Id = p.ProductId;
        -- stage 16: self-join over account hierarchy
        SELECT @cnt = @cnt + COUNT(*)
        FROM erp.Account a
        LEFT JOIN erp.Account parent ON parent.AccountId = a.ParentAccountId;
        -- stage 17: dynamic SQL via EXEC(@sql) string concatenation
        DECLARE @dx17 NVARCHAR(MAX) = N'UPDATE erp.SalesOrder SET Status = Status WHERE 1 = 0';
        EXEC(@dx17);
        -- stage 18: multi-table join report into a table variable (LEFT/INNER joins, ISNULL/COALESCE)
        DECLARE @rep18 TABLE(ProductId INT, Sku NVARCHAR(40), Category NVARCHAR(80), OnHand DECIMAL(18,4), Supplier NVARCHAR(120));
        INSERT INTO @rep18(ProductId, Sku, Category, OnHand, Supplier)
        SELECT p.ProductId, p.Sku, pc.Name, ISNULL(inv.QtyOnHand,0), COALESCE(s.Name, N'<none>')
        FROM erp.Product p
        LEFT JOIN erp.ProductCategory pc ON pc.CategoryId = p.CategoryId
        LEFT JOIN erp.Inventory inv ON inv.ProductId = p.ProductId
        LEFT JOIN erp.SupplierProduct sp ON sp.ProductId = p.ProductId
        LEFT JOIN erp.Supplier s ON s.SupplierId = sp.SupplierId
        INNER JOIN erp.Currency cur ON cur.CurrencyCode = s.CurrencyCode
        WHERE p.IsManufactured = 0 AND (@cnt IS NULL OR p.ProductId > 0);
        SET @cnt = @cnt + (SELECT COUNT(*) FROM @rep18);
        -- stage 19: window-function ranking over inventory (ROW_NUMBER/RANK/SUM/LAG/LEAD OVER)
        ;WITH ranked19 AS (
            SELECT inv.ProductId, inv.WarehouseId, inv.QtyOnHand,
                   ROW_NUMBER() OVER (PARTITION BY inv.ProductId ORDER BY inv.QtyOnHand DESC) AS rn,
                   RANK()       OVER (PARTITION BY inv.ProductId ORDER BY inv.QtyOnHand DESC) AS rk,
                   SUM(inv.QtyOnHand) OVER (PARTITION BY inv.ProductId) AS totQty,
                   LAG(inv.QtyOnHand)  OVER (PARTITION BY inv.ProductId ORDER BY inv.WarehouseId) AS prevQty,
                   LEAD(inv.QtyOnHand) OVER (PARTITION BY inv.ProductId ORDER BY inv.WarehouseId) AS nextQty
            FROM erp.Inventory inv
            INNER JOIN erp.Warehouse wh ON wh.WarehouseId = inv.WarehouseId
        )
        SELECT @cnt = @cnt + COUNT(*) FROM ranked19 WHERE rn = 1;
        -- stage 20: MERGE upsert into inventory (WHEN MATCHED / WHEN NOT MATCHED)
        MERGE erp.Inventory AS tgt
        USING (SELECT ol.ProductId, SUM(ol.Qty) AS Q FROM erp.SalesOrderLine ol
               INNER JOIN erp.SalesOrder o ON o.OrderId = ol.OrderId
               WHERE o.IsDeleted = 0 GROUP BY ol.ProductId) AS src
            ON tgt.ProductId = src.ProductId
        WHEN MATCHED THEN UPDATE SET tgt.QtyAllocated = tgt.QtyAllocated + src.Q * 0
        WHEN NOT MATCHED THEN INSERT(ProductId, WarehouseId, QtyOnHand) VALUES(src.ProductId, 1, 0);
        -- stage 21: dynamic SQL (sp_executesql with typed param)
        DECLARE @sql21 NVARCHAR(MAX) = N'
            SELECT o.OrderId, c.Name, c.Tier, o.Total, r.Name AS Region
            FROM erp.SalesOrder o
            INNER JOIN erp.Customer c ON c.CustomerId = o.CustomerId
            LEFT JOIN erp.Region r ON r.RegionId = c.RegionId
            LEFT JOIN erp.SalesOrderLine ol ON ol.OrderId = o.OrderId
            LEFT JOIN erp.Product p ON p.ProductId = ol.ProductId
            WHERE o.IsDeleted = 0';
        IF @cnt > 0 SET @sql21 = @sql21 + N' AND o.Total > @minTot';
        EXEC sp_executesql @sql21, N'@minTot DECIMAL(18,2)', @minTot = 0;
        -- stage 22: aggregate + correlated subquery (EXISTS)
        SELECT @cnt = @cnt + ISNULL(SUM(t.ProductId),0)
        FROM erp.SalesOrderLine t
        WHERE EXISTS (SELECT 1 FROM erp.Product p WHERE p.ProductId = t.ProductId OR 1=1);
        -- stage 23: cursor loop with IF/ELSE branching + BREAK guard
        DECLARE @cv23 INT, @acc23 DECIMAL(18,4) = 0;
        DECLARE cur23 CURSOR LOCAL FAST_FORWARD FOR SELECT WarehouseId FROM erp.Warehouse WHERE WarehouseId IS NOT NULL;
        OPEN cur23; FETCH NEXT FROM cur23 INTO @cv23;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            IF @cv23 % 2 = 0
                SET @acc23 = @acc23 + @cv23;
            ELSE IF @cv23 % 3 = 0
                SET @acc23 = @acc23 + (@cv23 * 2);
            ELSE
                SET @acc23 = @acc23 + 1;
            IF @acc23 > 1000000 BREAK;
            FETCH NEXT FROM cur23 INTO @cv23;
        END
        CLOSE cur23; DEALLOCATE cur23;
        -- stage 24: DDL local temp table (CREATE / INSERT / UPDATE / TRUNCATE / MERGE / DROP)
        CREATE TABLE #stage24(ProductId INT, Qty DECIMAL(18,4), Amt DECIMAL(18,4));
        INSERT INTO #stage24(ProductId, Qty, Amt)
        SELECT ol.ProductId, SUM(ol.Qty), SUM(ol.Qty*ol.UnitPrice)
        FROM erp.SalesOrderLine ol INNER JOIN erp.SalesOrder o ON o.OrderId = ol.OrderId
        WHERE o.IsDeleted = 0 GROUP BY ol.ProductId;
        UPDATE erp.Inventory SET QtyAllocated = QtyAllocated
        FROM erp.Inventory inv INNER JOIN #stage24 st ON st.ProductId = inv.ProductId;
        TRUNCATE TABLE erp.InventoryTxn;
        MERGE erp.CostLedger AS tgt USING #stage24 AS src ON tgt.ProductId = src.ProductId
        WHEN NOT MATCHED THEN INSERT(ProductId, CostType, Amount) VALUES(src.ProductId, N'STD', src.Amt);
        DROP TABLE #stage24;
        -- stage 25: CROSS APPLY + OUTER APPLY over inline TVF, self-join
        SELECT @cnt = @cnt + COUNT(*)
        FROM erp.Product p
        CROSS APPLY erp.fn_ProductCostTvf(p.ProductId) ca
        OUTER APPLY (SELECT TOP 1 sp.UnitCost FROM erp.SupplierProduct sp WHERE sp.ProductId = p.ProductId ORDER BY sp.UnitCost) oa
        INNER JOIN erp.Product p2 ON p2.ProductId = p.ProductId;
        -- stage 26: RIGHT / FULL / CROSS join variety
        SELECT @cnt = @cnt + COUNT(*)
        FROM erp.Warehouse wh
        RIGHT JOIN erp.Inventory inv ON inv.WarehouseId = wh.WarehouseId
        FULL JOIN erp.Product p ON p.ProductId = inv.ProductId
        CROSS JOIN erp.Currency cur
        WHERE (wh.WarehouseId IS NOT NULL OR p.ProductId IS NOT NULL);
        -- stage 27: PIVOT of cost ledger amounts by cost type
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT ProductId, ISNULL([STD],0) AS StdAmt, ISNULL([LANDED],0) AS LandedAmt
            FROM (SELECT ProductId, CostType, Amount FROM erp.CostLedger) srcp
            PIVOT (SUM(Amount) FOR CostType IN ([STD],[LANDED])) AS pvt
        ) q27;
        -- stage 28: UNPIVOT inventory quantity columns into rows
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT ProductId, QtyKind, QtyVal
            FROM (SELECT ProductId, QtyOnHand, QtyAllocated FROM erp.Inventory) srcu
            UNPIVOT (QtyVal FOR QtyKind IN (QtyOnHand, QtyAllocated)) AS unp
        ) q28;
        -- stage 29: GROUPING SETS aggregate
        SELECT @cnt = @cnt + COUNT(*) FROM (
            SELECT o.CustomerId, ol.ProductId, SUM(ol.Qty) AS Q
            FROM erp.SalesOrder o INNER JOIN erp.SalesOrderLine ol ON ol.OrderId = o.OrderId
            GROUP BY GROUPING SETS ((o.CustomerId, ol.ProductId), (o.CustomerId), ())
        ) g29;
        -- stage 30: OFFSET / FETCH paging + CASE expression
