            LEFT JOIN erp.Product p ON p.ProductId = ol.ProductId
            WHERE o.IsDeleted = 0';
        IF @cnt > 0 SET @sql39 = @sql39 + N' AND o.Total > @minTot';
        EXEC sp_executesql @sql39, N'@minTot DECIMAL(18,2)', @minTot = 0;
        -- stage 40: aggregate + correlated subquery (EXISTS)
        SELECT @cnt = @cnt + ISNULL(SUM(t.ProductId),0)
        FROM erp.SalesOrderLine t
