/*======================================================================
  usp_Stage11  --  node 11 of the deep reachable stage chain
======================================================================*/
CREATE PROCEDURE erp.usp_Stage11
    @Seed INT = 0
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @cnt INT = ISNULL(@Seed, 0), @f DECIMAL(9,4) = 1, @u DECIMAL(18,4) = 0;
    -- real DML: aggregate read over a base table
    SELECT @cnt = @cnt + COUNT(*) FROM erp.Product;
    -- scalar UDF calls (reachable)
    SET @f = erp.fn_DiscountFactor(CAST(@cnt AS DECIMAL(18,2)));
    SET @u = erp.fn_UnitCost(1, 1);
    SET @u = @u + erp.fn_OrderTotal(100);
    SET @f = @f + erp.fn_SupplierScore(1);
    -- table-valued UDFs via CROSS APPLY / FROM (all reachable, no orphans)
    SELECT @cnt = @cnt + COUNT(*)
    FROM erp.Product p CROSS APPLY erp.fn_ProductCostTvf(p.ProductId) x;
    SELECT @cnt = @cnt + COUNT(*) FROM erp.fn_ExplodeBomTvf(1, 1);
    SELECT @cnt = @cnt + COUNT(*) FROM erp.fn_OrderLinesTvf(100);
    -- DML write + audit
    INSERT INTO erp.AuditTrail(Area, RefId, Action, Detail)
    VALUES(N'usp_Stage11', @cnt, N'STEP', CONCAT(N'f=', @f, N' u=', @u));
    UPDATE erp.Inventory SET QtyAllocated = QtyAllocated WHERE 1 = 0;
    -- descend to next node
        EXEC erp.usp_Stage12 @Seed = @cnt;
END;
GO

