            IF @cv149 % 2 = 0
                SET @acc149 = @acc149 + @cv149;
            ELSE IF @cv149 % 3 = 0
                SET @acc149 = @acc149 + (@cv149 * 2);
            ELSE
                SET @acc149 = @acc149 + 1;
